    public Content $content;
    public function __construct(public Database $db,public array $config,public string $root){$this->content=new Content($db,$config,$root);self::schema($db->pdo());}
    public static function schema(PDO $pdo):void {
        if($pdo->query("SELECT 1 FROM byp_migrations WHERE migration='2026_11_08_gallery_v1'")->fetchColumn())return;
        $sql=[
          'byp_shop_limits'=>'bucket CHAR(64) PRIMARY KEY,hits INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL',
          'byp_shop_groups'=>'id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kind VARCHAR(20) NOT NULL,title VARCHAR(120) NOT NULL,description TEXT NOT NULL,image VARCHAR(500) NOT NULL DEFAULT "",UNIQUE KEY(kind,title)',
          'byp_shop_products'=>'id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(120) NOT NULL UNIQUE,title VARCHAR(190) NOT NULL,category VARCHAR(120) NOT NULL,collection VARCHAR(120) NOT NULL,brand VARCHAR(120) NOT NULL,description TEXT NOT NULL,specs TEXT NOT NULL,images TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT "draft",revision INT NOT NULL DEFAULT 1,updated_at DATETIME NOT NULL,INDEX(status,category)',
          'byp_shop_variants'=>'id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED NOT NULL,sku VARCHAR(100) NOT NULL UNIQUE,title VARCHAR(190) NOT NULL,price BIGINT UNSIGNED NOT NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(product_id) REFERENCES byp_shop_products(id),INDEX(product_id)',
          'byp_shop_carts'=>'actor CHAR(64) PRIMARY KEY,data TEXT NOT NULL,updated_at DATETIME NOT NULL',
          'byp_shop_orders'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference CHAR(24) NOT NULL UNIQUE,actor CHAR(64) NOT NULL,request_key CHAR(64) NOT NULL UNIQUE,payload_hash CHAR(64) NOT NULL,contact TEXT NOT NULL,shipping VARCHAR(30) NOT NULL,promo VARCHAR(100) NOT NULL,subtotal BIGINT UNSIGNED NOT NULL,discount BIGINT UNSIGNED NOT NULL,delivery BIGINT UNSIGNED NOT NULL,total BIGINT UNSIGNED NOT NULL,state VARCHAR(30) NOT NULL DEFAULT "pending",fulfillment VARCHAR(30) NOT NULL DEFAULT "new",refund_requested TINYINT NOT NULL DEFAULT 0,refunded BIGINT UNSIGNED NOT NULL DEFAULT 0,stock_released TINYINT NOT NULL DEFAULT 0,consent_at DATETIME NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(actor,created_at)',
          'byp_shop_items'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,variant_id INT UNSIGNED NOT NULL,title VARCHAR(400) NOT NULL,sku VARCHAR(100) NOT NULL,price BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES byp_shop_orders(id),FOREIGN KEY(variant_id) REFERENCES byp_shop_variants(id)',
          'byp_shop_payments'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,operation CHAR(36) NOT NULL UNIQUE,provider_id CHAR(36) NULL UNIQUE,shop_id VARCHAR(100) NOT NULL,mode VARCHAR(10) NOT NULL,body TEXT NOT NULL,state VARCHAR(30) NOT NULL DEFAULT "creating",confirmation VARCHAR(1000) NOT NULL DEFAULT "",last_error TEXT NULL,created_at DATETIME NOT NULL,last_checked_at DATETIME NULL,FOREIGN KEY(order_id) REFERENCES byp_shop_orders(id)',
          'byp_shop_refunds'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,operation CHAR(36) NOT NULL UNIQUE,provider_id CHAR(36) NULL UNIQUE,amount BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,state VARCHAR(30) NOT NULL DEFAULT "pending",last_error TEXT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(order_id) REFERENCES byp_shop_orders(id)',
          'byp_shop_mail'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(190) NOT NULL UNIQUE,state VARCHAR(30) NOT NULL DEFAULT "pending",lease_until DATETIME NULL,last_error TEXT NULL,attempts INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,FOREIGN KEY(order_id) REFERENCES byp_shop_orders(id)'
        ];
