    }
    public static function money(int $minor):string{return Content::money($minor);}
    public static function uuid():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-a'.substr($h,17,3).'-'.substr($h,20);}
    public function actor(string $token):string{return hash_hmac('sha256',$token,$this->config['app']['key']);}
    public function settings(bool $secret=false):array {
        $s=['enabled'=>false,'mode'=>'test','shop_id'=>'','shop_secret'=>'','smtp_enabled'=>false,'smtp_host'=>'','smtp_port'=>587,'smtp_security'=>'starttls','smtp_user'=>'','smtp_password'=>'','from_email'=>'','from_name'=>'Gallery','receipt_enabled'=>false,'tax_system'=>0,'vat_code'=>1,'shipping_cost'=>90000,'pickup_address'=>'','promo_code'=>'','promo_percent'=>0];
        $r=$this->db->one('SELECT setting_value FROM byp_settings WHERE setting_group="shop_private" AND setting_key="connection"');if($r)$s=array_replace($s,json_decode($r['setting_value'],true)??[]);
        foreach(['shop_secret','smtp_password']as $key){$cipher=$s[$key.'_cipher']??'';unset($s[$key.'_cipher']);$s[$key.'_saved']=$cipher!=='';$s[$key]=$secret&&$cipher!==''?LicenseCrypto::decrypt($cipher,$this->config['app']['key']):'';if(!$secret)unset($s[$key]);}return $s;
    }
    public function configure(array $v):void {
        $s=$this->settings(true);foreach(['enabled','smtp_enabled','receipt_enabled']as $k)$s[$k]=!empty($v[$k]);
        foreach(['shop_id','mode','smtp_host','smtp_security','smtp_user','from_email','from_name','pickup_address','promo_code']as $k)$s[$k]=trim((string)($v[$k]??$s[$k]));
        foreach(['smtp_port','tax_system','vat_code','shipping_cost','promo_percent']as $k)$s[$k]=(int)($v[$k]??$s[$k]);
        foreach(['shop_secret','smtp_password']as $k){if(!empty($v['clear_'.$k]))$s[$k]='';elseif(!empty($v[$k]))$s[$k]=(string)$v[$k];}
        if(!in_array($s['mode'],['test','live'],true)||!preg_match('/^[0-9]{0,20}$/D',$s['shop_id']))throw new RuntimeException('Проверьте режим и Shop ID.');
        if($s['enabled']&&(!$s['shop_id']||!$s['shop_secret']))throw new RuntimeException('Для оплаты нужны Shop ID и секретный ключ.');
        if($s['shipping_cost']<0||$s['shipping_cost']>100000000||$s['promo_percent']<0||$s['promo_percent']>90||!preg_match('/^[a-zA-Z0-9_-]{0,40}$/D',$s['promo_code']))throw new RuntimeException('Проверьте доставку и промокод.');
        if(!in_array($s['smtp_port'],[465,587],true)||!in_array($s['smtp_security'],['ssl','starttls'],true)||($s['smtp_security']==='ssl')!==($s['smtp_port']===465))throw new RuntimeException('Почта: SSL 465 или STARTTLS 587.');
        if($s['smtp_host']&&!preg_match('/^[a-zA-Z0-9][a-zA-Z0-9.-]{0,252}$/D',$s['smtp_host']))throw new RuntimeException('SMTP host без протокола и пути.');
        if($s['from_email'])CommerceSettings::email($s['from_email']);
        foreach($s as $value)if(is_string($value)&&(strlen($value)>2048||preg_match('/[\r\n\x00]/',$value)))throw new RuntimeException('Проверьте параметры подключения.');
        if($s['smtp_enabled'])foreach(['smtp_host','smtp_user','smtp_password','from_email']as $k)if(!$s[$k])throw new RuntimeException('Заполните SMTP, отправителя и пароль.');
        if(!in_array($s['vat_code'],range(1,12),true)||!in_array($s['tax_system'],range(0,6),true))throw new RuntimeException('Проверьте настройки чеков.');
        $old=$this->settings(true);$bindingChanged=$s['shop_id']!==$old['shop_id']||$s['mode']!==$old['mode'];
        if($bindingChanged&&$this->db->one('SELECT id FROM byp_shop_payments WHERE state NOT IN ("canceled","rejected") LIMIT 1'))throw new RuntimeException('Магазин связан с платежами. Смену магазина выполняйте отдельной миграцией, сохраняя доступ к возвратам.');
        foreach(['shop_secret','smtp_password']as $k){$s[$k.'_cipher']=$s[$k]?LicenseCrypto::encrypt($s[$k],$this->config['app']['key']):'';unset($s[$k],$s[$k.'_saved']);}
        $this->db->execute('INSERT INTO byp_settings(setting_group,setting_key,setting_value,value_type,is_public,updated_at) VALUES("shop_private","connection",?,"json",0,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()',[json_encode($s,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);
    }
    public function appearance():array {$s=$this->content->settings();$keys=array_column($this->db->all('SELECT setting_key FROM byp_settings WHERE setting_group="journal"'),'setting_key');foreach(['theme'=>is_file($this->root.'/themes/custom/page.html')?'custom':'gallery','tagline'=>'Вещи, с которыми хочется жить.','accent'=>'#604537','heading_font'=>'cormorant']as $k=>$v)if(!in_array($k,$keys,true))$s[$k]=$v;$s['site_url']=$this->config['app']['url'];return $s;}
    public function products(bool $public=true):array {
        $rows=$this->db->all('SELECT * FROM byp_shop_products'.($public?' WHERE status="published"':'').' ORDER BY id');$variants=[];foreach($this->db->all('SELECT * FROM byp_shop_variants ORDER BY id')as $v)$variants[$v['product_id']][]=$v;
        $seo=[];foreach($this->db->all('SELECT setting_key,setting_value FROM byp_settings WHERE setting_group="shop_seo"')as $r)$seo[$r['setting_key']]=json_decode($r['setting_value'],true)??[];
        foreach($rows as &$p){$p['images']=json_decode($p['images'],true)??[];$p['variants']=array_values(array_filter($variants[$p['id']]??[],fn($v)=>!$public||$v['active']));foreach(['seo_title','seo_description','canonical','noindex']as $key)$p[$key]=$seo['product-'.$p['id']][$key]??($key==='noindex'?false:'');}return $rows;
    }
    public function groups():array{return $this->db->all('SELECT * FROM byp_shop_groups ORDER BY kind,id');}
    public function saveGroup(array $v):void {
