        if(!in_array($kind,['category','collection','brand'],true)||!$title||mb_strlen($title)>120||mb_strlen($description)>5000||($image&&(!Content::url($image)||!str_starts_with($image,'/'))))throw new RuntimeException('Проверьте название, описание и изображение подборки.');
        $pdo=$this->db->pdo();$pdo->beginTransaction();try{$id=(int)($v['id']??0);$old=$id?$this->db->one('SELECT * FROM byp_shop_groups WHERE id=? FOR UPDATE',[$id]):null;if($id&&!$old)throw new RuntimeException('Подборка не найдена.');if($old&&$old['kind']!==$kind)throw new RuntimeException('Тип существующей подборки менять нельзя.');if($old){$this->db->execute('UPDATE byp_shop_groups SET title=?,description=?,image=? WHERE id=?',[$title,$description,$image,$id]);if($old['title']!==$title)$this->db->execute('UPDATE byp_shop_products SET '.$kind.'=?,revision=revision+1,updated_at=NOW() WHERE '.$kind.'=?',[$title,$old['title']]);}else $this->db->execute('INSERT INTO byp_shop_groups(kind,title,description,image) VALUES(?,?,?,?)',[$kind,$title,$description,$image]);$pdo->commit();}catch(Throwable $x){$pdo->rollBack();throw $x;}
    }
    public function saveProduct(array $v,int $user):int {
        foreach(['slug'=>120,'title'=>190,'category'=>120,'collection'=>120,'brand'=>120,'description'=>20000,'specs'=>5000]as $k=>$limit){$v[$k]=trim((string)($v[$k]??''));if(mb_strlen($v[$k])>$limit)throw new RuntimeException('Слишком длинное поле: '.$k);}
