        $images=is_array($v['images']??null)?$v['images']:preg_split('/\R/',trim((string)($v['images']??'')));$images=array_values(array_filter($images));if(count($images)>12)throw new RuntimeException('До 12 изображений.');foreach($images as $im)if(!Content::url($im)||!str_starts_with($im,'/')||str_starts_with($im,'//'))throw new RuntimeException('Выберите изображение из медиатеки.');
