        $pdo=$this->db->pdo();$pdo->beginTransaction();try{
            $id=(int)($v['id']??0);if($id){$old=$this->db->one('SELECT * FROM byp_shop_products WHERE id=? FOR UPDATE',[$id]);if(!$old||(int)$old['revision']!==(int)($v['revision']??0))throw new RuntimeException('Товар изменён другим сотрудником. Обновите страницу; ваш ввод сохранён в форме.');}
