            if($id)$this->db->execute('UPDATE byp_shop_products SET slug=?,title=?,category=?,collection=?,brand=?,description=?,specs=?,images=?,status=?,revision=revision+1,updated_at=NOW() WHERE id=?',[...$params,$id]);else $id=$this->db->insert('INSERT INTO byp_shop_products(slug,title,category,collection,brand,description,specs,images,status,updated_at) VALUES(?,?,?,?,?,?,?,?,?,NOW())',$params);
            $seo=['seo_title'=>mb_substr(trim($v['seo_title']??''),0,190),'seo_description'=>mb_substr(trim($v['seo_description']??''),0,500),'canonical'=>trim($v['canonical']??''),'noindex'=>!empty($v['noindex'])];if($seo['canonical']&&!preg_match('#^https?://#i',Content::url($seo['canonical'])))throw new RuntimeException('Canonical — полный URL http/https.');$this->db->execute('INSERT INTO byp_settings(setting_group,setting_key,setting_value,value_type,is_public,updated_at) VALUES("shop_seo",?, ?,"json",1,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()',['product-'.$id,json_encode($seo,JSON_UNESCAPED_UNICODE)]);
            foreach(['category','collection','brand']as $kind)if($v[$kind]!=='')$this->db->execute('INSERT IGNORE INTO byp_shop_groups(kind,title,description) VALUES(?,?,"")',[$kind,$v[$kind]]);
