            $this->db->execute('INSERT INTO byp_audit_logs(user_id,action,entity_type,entity_id,metadata,created_at) VALUES(?,"shop.product.save","shop_product",?,"{}",NOW())',[$user,$id]);$pdo->commit();return $id;
        }catch(Throwable $x){$pdo->rollBack();throw $x;}
    }
    public function cart(string $actor):array {$r=$this->db->one('SELECT data FROM byp_shop_carts WHERE actor=?',[$actor]);return $r?(json_decode($r['data'],true)??[]):[];}
    public function changeCart(string $actor,int $variant,int $qty,bool $add=false):void {
        if($qty<0||$qty>99)throw new RuntimeException('Количество от 0 до 99.');$pdo=$this->db->pdo();$pdo->beginTransaction();try{
            $this->db->execute('INSERT IGNORE INTO byp_shop_carts(actor,data,updated_at) VALUES(?,"{}",NOW())',[$actor]);$r=$this->db->one('SELECT data FROM byp_shop_carts WHERE actor=? FOR UPDATE',[$actor]);$cart=json_decode($r['data'],true)??[];$next=$add?(int)($cart[$variant]??0)+$qty:$qty;
            if($next){$v=$this->db->one('SELECT v.*,p.status FROM byp_shop_variants v JOIN byp_shop_products p ON p.id=v.product_id WHERE v.id=?',[$variant]);if(!$v||!$v['active']||$v['status']!=='published'||$next>min(99,(int)$v['stock']))throw new RuntimeException('Недостаточно товара в выбранном варианте.');$cart[$variant]=$next;}else unset($cart[$variant]);if(count($cart)>50)throw new RuntimeException('В корзине не более 50 вариантов.');
            $this->db->execute('UPDATE byp_shop_carts SET data=?,updated_at=NOW() WHERE actor=?',[json_encode($cart),$actor]);$pdo->commit();
        }catch(Throwable $x){$pdo->rollBack();throw $x;}
    }
    public function quote(string $actor,string $shipping='delivery',string $promo='',bool $lock=false):array {
        $s=$this->settings();if(!in_array($shipping,['delivery','pickup'],true)||($shipping==='pickup'&&!$s['pickup_address']))throw new RuntimeException('Способ доставки недоступен.');
        $cart=$this->cart($actor);ksort($cart,SORT_NUMERIC);$items=[];$subtotal=0;$issues=[];
        foreach($cart as $id=>$qty){$v=$this->db->one('SELECT v.*,p.title product_title,p.slug,p.images,p.status FROM byp_shop_variants v JOIN byp_shop_products p ON p.id=v.product_id WHERE v.id=?'.($lock?' FOR UPDATE':''),[(int)$id]);if(!$v||!$v['active']||$v['status']!=='published'||(int)$v['stock']<(int)$qty)$issues[]='Товар '.($v['product_title']??'#'.$id).' недоступен в нужном количестве.';if(!$v)continue;$items[]=$v+['quantity'=>(int)$qty];$subtotal+=(int)$v['price']*(int)$qty;}
        $promo=strtoupper(trim($promo));if($promo!==''&&($s['promo_code']===''||strtoupper($s['promo_code'])!==$promo||!$s['promo_percent']))throw new RuntimeException('Промокод не действует.');
        $discount=$promo?intdiv($subtotal*$s['promo_percent'],100):0;$delivery=$shipping==='delivery'&&$items?(int)$s['shipping_cost']:0;$total=$subtotal-$discount+$delivery;
        if($total>9999999999)throw new RuntimeException('Стоимость заказа превышает допустимую.');$hash=hash('sha256',json_encode([$cart,array_map(fn($i)=>[$i['id'],$i['price']],$items),$shipping,$promo,$discount,$delivery]));
        return compact('items','subtotal','discount','delivery','total','hash','shipping','promo','issues');
    }
    public static function contact(array $v):array {
        $labels=['name'=>'Имя','email'=>'Email','phone'=>'Телефон','address'=>'Адрес доставки'];
        foreach(['name'=>150,'email'=>190,'phone'=>60,'address'=>1000]as $k=>$limit){$v[$k]=trim((string)($v[$k]??''));if(mb_strlen($v[$k])>$limit)throw new RuntimeException('Слишком длинное поле «'.$labels[$k].'».');}
        if(!$v['name'])throw new RuntimeException('Укажите имя получателя.');
        if(!filter_var($v['email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Укажите корректный email.');
        $digits=preg_replace('/[^0-9]/','',$v['phone']);
        if(!preg_match('/^[+0-9 ()-]{7,60}$/D',$v['phone'])||strlen($digits)<7||strlen($digits)>15)throw new RuntimeException('Укажите корректный телефон: от 7 до 15 цифр, можно использовать +, пробелы, скобки и дефисы.');
        if(empty($v['terms']))throw new RuntimeException('Подтвердите условия покупки, доставки и возврата.');
        if(empty($v['consent']))throw new RuntimeException('Подтвердите согласие на обработку данных для заказа.');
        if(($v['shipping']??'delivery')==='delivery'&&!$v['address'])throw new RuntimeException('Укажите адрес доставки.');
        return array_intersect_key($v,array_flip(['name','email','phone','address']));
    }
    public function checkout(string $actor,array $v):array {
        $contact=self::contact($v);if(!preg_match('/^[a-f0-9]{32}$/D',$v['token']??''))throw new RuntimeException('Обновите форму заказа.');$request=hash('sha256',$actor.$v['token']);$payload=hash('sha256',json_encode([$contact,$v['shipping']??'delivery',$v['promo']??'',$v['quote']??'']));$pdo=$this->db->pdo();$pdo->beginTransaction();try{
            $this->db->execute('INSERT IGNORE INTO byp_shop_carts(actor,data,updated_at) VALUES(?,"{}",NOW())',[$actor]);$this->db->one('SELECT actor FROM byp_shop_carts WHERE actor=? FOR UPDATE',[$actor]);$old=$this->db->one('SELECT * FROM byp_shop_orders WHERE request_key=?',[$request]);if($old){if(!hash_equals($old['payload_hash'],$payload))throw new RuntimeException('Этот заказ уже сохранён с другими данными. Откройте его или начните новый.');$pdo->commit();return $old;}
