        }
        if($delivery)$out[]=['description'=>'Доставка','quantity'=>'1','amount'=>['value'=>PaymentGateway::amount($delivery),'currency'=>'RUB'],'vat_code'=>$vat,'payment_mode'=>'full_prepayment','payment_subject'=>'service'];
