        foreach($seed['pages']as $p){$pdo->prepare('INSERT IGNORE INTO byp_pages(author_id,slug,title,excerpt,content,blocks,template,status,published_at,created_at,updated_at) VALUES(?,?,?,?,?,"[]","gallery",?,?,NOW(),NOW())')->execute([$user,$p['slug'],$p['title'],$p['excerpt'],$p['content'],in_array($p['slug'],['about','contact'],true)?'published':'draft',in_array($p['slug'],['about','contact'],true)?gmdate('Y-m-d H:i:s'):null]);}
        $pdo->prepare('INSERT IGNORE INTO byp_settings(setting_group,setting_key,setting_value,value_type,is_public,updated_at) VALUES("journal","site_name",?,"string",1,NOW())')->execute([$site]);
